// GERADO por tools/sync-pivo-lib.mjs a partir de firmware-libs/pivo_local/ — NAO editar aqui.
// Pivo na TON (sequencia local): lib pivo_local + glue pivo.cpp. docs/IOT-PIVO-TON-LOCAL.md
// Carregado ANTES dos geradores (iot-diagram.tsx e tools/fw-regress).
var PivoLocalGen = (function () {
  var FILES = {
    "include/pivo_local.h": "// ============================================================================\n// pivo_local — maquina de estados do PIVO na TON slave (sequencia local, sem internet).\n// Spec: arquivos/Spec NexON - Automacao do pivo (protocolo e firmware).md (v1.0, 11/11/2026)\n//       + decisoes do usuario em 12/11/2026 (docs/IOT-PIVO-TON-LOCAL.md).\n//\n// C++ PURO (sem Arduino): compila no host (test_pivo.cpp) e no ESP32 dentro do\n// firmware gerado. Quem le as BI, aciona reles, roda o ciclo do percentimetro,\n// publica e guarda NVS e' o glue (glue/pivo.cpp) — esta lib so' decide.\n// Fonte canonica: AupusNexOn/firmware-libs/pivo_local/. Os geradores (V1 e V2)\n// embutem uma COPIA identica (tools/sync-pivo-lib.mjs --check confere).\n//\n// Saidas: BO1 bombeamento, BO2 valvula, BO3 direita, BO4 esquerda, BO5 percentimetro, BO6 canhao.\n// Entradas SEMANTICAS (polaridade ja' resolvida pelo glue):\n//   pressao (BI1, 1 = ok) · tensao (BI2, 1 = ok) · gir_dir/gir_esq (BI3/BI4, retorno do sentido)\n//   seguranca (BI5, 1 = ok; 0 ou sem sinal = atuou) · canhao (BI6, retorno do canhao)\n// Angulo: valor BRUTO do encoder, 0..359 (a calibracao fica no app).\n// ============================================================================\n#ifndef PIVO_LOCAL_H\n#define PIVO_LOCAL_H\n\n#include <stdint.h>\n#include <stddef.h>\n\nnamespace pivo {\n\n// Etapa (spec 7.3): parado · aguardando_pressao (partida: pressao ou giro) · girando\nenum Estado : uint8_t { PARADO = 0, PARTINDO = 1, GIRANDO = 2 };\nconst char* estadoNome(Estado e);\n\n// Passo da partida (dentro de PARTINDO)\nenum Passo : uint8_t { P_NENHUM = 0, P_PRESSAO = 1, P_GIRO = 2 };\nconst char* passoNome(Passo p);\n\n// Motivo da ultima parada (spec 8.6) + extras desta implementacao (9..)\nenum Motivo : uint8_t {\n    M_NENHUMA = 0, M_CONCLUIDA = 1, M_COMANDO = 2, M_QUEDA_PRESSAO = 3, M_PRESSAO_NAO_SUBIU = 4,\n    M_TENSAO = 5, M_SEGURANCA = 6, M_REINICIO = 7, M_CONDICAO_PARTIDA = 8,\n    M_NAO_GIROU = 9,      // o sentido nao confirmou (BI3/BI4) no tempo\n    M_LADO_CAIU = 10,     // o retorno do sentido caiu com o pivo girando (parou sem comando)\n    M_FALHA_RELES = 11,   // expansor de reles sem controle (glue)\n};\nconst char* motivoNome(uint8_t m);\n\n// Alertas (spec 8.6): bit0 erro de posicao · bit1 falha no canhao · bit2 reinicios repetidos (glue)\nenum Alerta : uint8_t { A_ERRO_POSICAO = 1, A_FALHA_CANHAO = 2, A_REINICIOS = 4 };\n\nenum Parada : uint8_t {\n    POR_GRAUS = 0,    // graus a percorrer a partir da posicao atual (voltas = 360 x n, no NexON)\n    POR_DURACAO = 1,  // PROVISORIO: pivo sem encoder (tempo estimado no NexON) — sai quando houver encoder de teste\n};\n\nstatic const int ID_LEN = 12;\n\nstruct Config {\n    bool tem_valvula   = false;   // BO2\n    bool tem_canhao    = true;    // BO6\n    bool tem_pressao   = true;    // BI1\n    bool tem_tensao    = true;    // BI2\n    bool tem_gir_dir   = true;    // BI3\n    bool tem_gir_esq   = true;    // BI4\n    bool tem_seguranca = true;    // BI5\n    bool tem_canhao_st = true;    // BI6\n    uint32_t espera_pressao_ms  = 60000;    // partida: pressao tem de subir em ate' (sem BI1 = espera fixa)\n    uint32_t confirma_giro_ms   = 30000;    // partida: sentido confirmado (BI3/BI4) em ate'\n    uint32_t confirma_canhao_ms = 5000;     // canhao ligado sem BI6 por isto -> alerta falha_canhao\n    uint32_t tol_pressao_ms     = 0;        // girando: pressao em 0 por isto -> desliga (0 = na hora)\n    uint32_t tol_tensao_ms      = 0;        // girando: tensao em 0 por isto -> desliga (0 = na hora)\n    uint32_t tol_lado_ms        = 0;        // girando: retorno do sentido em 0 por isto -> desliga\n    uint32_t sem_posicao_ms     = 30000;    // sem leitura do encoder por isto -> alerta erro_posicao (nao para)\n    uint32_t janela_giro_ms     = 600000;   // \"angulo mudando\" dentro desta janela\n};\n\nstruct Plano {\n    char     id[ID_LEN] = {0};    // id da ordem (8 caracteres)\n    char     dir        = 'D';    // 'D' direita | 'E' esquerda\n    bool     com_agua   = true;\n    int16_t  pm         = 1000;   // percentimetro em permil (0..1000). Sem agua => 1000\n    bool     canhao     = false;\n    bool     tem_faixa  = false;  // faixa do canhao: dentro de [desliga_em, liga_em] o canhao fica OFF\n    uint16_t desliga_em = 0;      // 0..359 (bruto do encoder)\n    uint16_t liga_em    = 0;      // 0..359\n    Parada   parada     = POR_GRAUS;\n    uint32_t graus      = 360;    // POR_GRAUS (>0)\n    uint32_t duracao_s  = 0;      // POR_DURACAO (>0)\n};\nbool validarPlano(Plano& p, char* motivo, size_t msz);\n\nstruct Entradas {\n    bool pressao   = false;\n    bool tensao    = false;\n    bool gir_dir   = false;\n    bool gir_esq   = false;\n    bool seguranca = false;   // 1 = ok\n    bool canhao    = false;\n};\n\nstruct Saidas {\n    bool    bomba   = false;\n    bool    valvula = false;\n    bool    dir     = false;\n    bool    esq     = false;\n    bool    canhao  = false;\n    int16_t perc_pm = -1;     // BO5: ciclo do percentimetro (glue); -1 = desligado\n};\n\n// Eventos (glue: <base>/pivo/evento na TON com WiFi; o satelite LoRa nao manda).\n//   tipo: \"ligar\" | \"passo\" | \"girando\" | \"alerta\" | \"parado\"\nstruct Ouvinte {\n    virtual ~Ouvinte() {}\n    virtual void aoEvento(const char* tipo, const char* detalhe) = 0;\n    virtual void aoMudarEstado(Estado de, Estado para) = 0;\n};\n\nclass Maquina {\npublic:\n    Maquina(const Config& cfg, Ouvinte* ouv);\n    void configurar(const Config& cfg) { _cfg = cfg; }\n    const Config& config() const { return _cfg; }\n\n    void tick(uint32_t now_ms, const Entradas& in);\n    const Saidas& saidas() const { return _out; }\n    void posicao(float graus_bruto, uint32_t now_ms);   // cada leitura boa do encoder (0..359)\n\n    // Comandos. false + motivo quando recusam.\n    bool ligar(const Plano& p, uint32_t now_ms, char* motivo, size_t msz);\n    void desligar(uint8_t motivo, uint32_t now_ms);     // SEMPRE desliga (tudo LOW, spec 6.6)\n    bool ajustarPercentimetro(int16_t pm, char* motivo, size_t msz);\n    bool ajustarCanhao(bool ligado, bool tem_faixa, uint16_t desliga_em, uint16_t liga_em, uint32_t now_ms, char* motivo, size_t msz);\n    void marcarMotivo(uint8_t m) { _motivo = m; }       // glue: reinicio (boot)\n    void marcarAlerta(uint8_t a) { _alertas |= a; }     // glue: reinicios repetidos (watchdog)\n    uint32_t tempoGirandoMs(uint32_t now) const { return _st == PARADO ? 0 : now - _t_ligar; }\n\n    // Observabilidade\n    Estado      estado() const { return _st; }\n    Passo       passo() const { return _passo; }\n    const Plano& plano() const { return _plano; }\n    uint8_t     motivo() const { return _motivo; }      // motivo da ultima parada\n    uint8_t     alertas() const { return _alertas; }\n    bool        temPosicao() const { return _tem_pos; }\n    float       angulo() const { return _ang; }\n    float       percorrido() const;                     // graus desde a partida (deslocamento liquido, modulo)\n    uint32_t    alvo() const { return _plano.parada == POR_GRAUS ? _plano.graus : 0; }\n    bool        girando(uint32_t now_ms) const;\n    const Entradas& entradas() const { return _in; }\n    bool        otaPermitida() const { return _st == PARADO; }\n\nprivate:\n    void _ir(Estado e);\n    void _evento(const char* t, const char* d) { if (_ouv) _ouv->aoEvento(t, d); }\n    void _acionarLado(uint32_t now);\n    void _entrarGirando(uint32_t now);\n    void _avaliarCanhao(uint32_t now);\n    bool _canhaoNaFaixaOff() const;\n    bool _gir() const { return _plano.dir == 'D' ? _in.gir_dir : _in.gir_esq; }\n    bool _temGir() const { return _plano.dir == 'D' ? _cfg.tem_gir_dir : _cfg.tem_gir_esq; }\n    bool _queda(bool ok, uint32_t& desde, uint32_t tol, uint32_t now);\n\n    Config   _cfg;\n    Ouvinte* _ouv;\n    Estado   _st = PARADO;\n    Passo    _passo = P_NENHUM;\n    Saidas   _out;\n    Entradas _in;\n    Plano    _plano;\n    uint8_t  _motivo = M_NENHUMA;\n    uint8_t  _alertas = 0;\n    uint32_t _t_passo = 0;\n    uint32_t _t_ligar = 0;\n    // posicao\n    bool     _tem_pos = false;\n    float    _ang = 0;\n    uint32_t _t_pos = 0;\n    float    _ang_ref = 0;\n    uint32_t _t_ang_mudou = 0;\n    bool     _ang_mudou_ok = false;\n    bool     _contando = false;\n    float    _soma = 0;            // soma dos deslocamentos (com sinal); percorrido = |soma|\n    // canhao\n    uint32_t _t_canhao_sem = 0;    // desde quando o canhao esta' ligado sem BI6 (0 = ok)\n    // quedas (0 = ok)\n    uint32_t _q_pressao = 0, _q_tensao = 0, _q_lado = 0;\n};\n\n} // namespace pivo\n\n#endif // PIVO_LOCAL_H\n",
    "src/pivo_local.cpp": "// pivo_local.cpp — ver pivo_local.h. C++ puro.\n#include \"pivo_local.h\"\n#include <string.h>\n#include <stdio.h>\n\nnamespace pivo {\n\nconst char* estadoNome(Estado e) {\n    switch (e) {\n        case PARADO:   return \"parado\";\n        case PARTINDO: return \"aguardando_pressao\";\n        case GIRANDO:  return \"girando\";\n    }\n    return \"?\";\n}\n\nconst char* passoNome(Passo p) {\n    switch (p) {\n        case P_NENHUM:  return \"\";\n        case P_PRESSAO: return \"pressao\";\n        case P_GIRO:    return \"giro\";\n    }\n    return \"?\";\n}\n\nconst char* motivoNome(uint8_t m) {\n    switch (m) {\n        case M_NENHUMA: return \"nenhuma\";\n        case M_CONCLUIDA: return \"concluida\";\n        case M_COMANDO: return \"comando_operador\";\n        case M_QUEDA_PRESSAO: return \"queda_pressao\";\n        case M_PRESSAO_NAO_SUBIU: return \"pressao_nao_subiu\";\n        case M_TENSAO: return \"tensao\";\n        case M_SEGURANCA: return \"seguranca\";\n        case M_REINICIO: return \"reinicio_slave\";\n        case M_CONDICAO_PARTIDA: return \"condicao_partida\";\n        case M_NAO_GIROU: return \"nao_girou\";\n        case M_LADO_CAIU: return \"lado_caiu\";\n        case M_FALHA_RELES: return \"falha_reles\";\n    }\n    return \"?\";\n}\n\nstatic float norm360(float g) {\n    while (g >= 360.0f) g -= 360.0f;\n    while (g < 0.0f) g += 360.0f;\n    return g;\n}\nstatic float dif180(float a, float b) {          // menor caminho b - a, em (-180, 180]\n    float d = norm360(b - a);\n    return d > 180.0f ? d - 360.0f : d;\n}\nstatic float absf(float x) { return x < 0 ? -x : x; }\nstatic void copia(char* dst, const char* src, size_t n) {\n    if (!dst || !n) return;\n    if (!src) src = \"\";\n    strncpy(dst, src, n - 1);\n    dst[n - 1] = 0;\n}\n\nstatic const float SALTO_MAX_GRAUS = 30.0f;   // leitura que pula mais que isso = glitch, nao conta\nstatic const float MUDOU_GRAUS     = 0.5f;    // abaixo disso nao conta como \"angulo mudando\"\n\nbool validarPlano(Plano& p, char* motivo, size_t msz) {\n    if (p.dir != 'D' && p.dir != 'E') { copia(motivo, \"direcao\", msz); return false; }\n    if (p.pm < 0 || p.pm > 1000) { copia(motivo, \"percentimetro\", msz); return false; }\n    if (p.parada == POR_GRAUS) {\n        if (p.graus == 0 || p.graus > 360UL * 50UL) { copia(motivo, \"parada\", msz); return false; }\n    } else if (p.parada == POR_DURACAO) {\n        if (p.duracao_s == 0 || p.duracao_s > 7UL * 86400UL) { copia(motivo, \"duracao\", msz); return false; }\n    } else { copia(motivo, \"parada\", msz); return false; }\n    if (p.tem_faixa && (p.desliga_em > 359 || p.liga_em > 359)) { copia(motivo, \"faixa\", msz); return false; }\n    if (!p.com_agua) { p.pm = 1000; p.canhao = false; }   // sem agua: 100 % e canhao LOW (spec 6.3)\n    p.id[ID_LEN - 1] = 0;\n    if (motivo && msz) motivo[0] = 0;\n    return true;\n}\n\nMaquina::Maquina(const Config& cfg, Ouvinte* ouv) : _cfg(cfg), _ouv(ouv) {}\n\nvoid Maquina::_ir(Estado e) {\n    if (e == _st) return;\n    Estado de = _st;\n    _st = e;\n    if (_ouv) _ouv->aoMudarEstado(de, e);\n}\n\nbool Maquina::_queda(bool ok, uint32_t& desde, uint32_t tol, uint32_t now) {\n    if (ok) { desde = 0; return false; }\n    if (!desde) desde = now ? now : 1;\n    return (now - desde) >= tol;\n}\n\nfloat Maquina::percorrido() const { return absf(_soma); }\n\nbool Maquina::girando(uint32_t now) const {\n    return _st == GIRANDO && _out.perc_pm > 0 && _ang_mudou_ok && (now - _t_ang_mudou) < _cfg.janela_giro_ms;\n}\n\n// ---------------------------------------------------------------- comandos\n\nbool Maquina::ligar(const Plano& p, uint32_t now, char* motivo, size_t msz) {\n    if (_st != PARADO) { copia(motivo, \"ja_ligado\", msz); return false; }\n    Plano q = p;\n    char m[24];\n    if (!validarPlano(q, m, sizeof(m))) {\n        char t[40];\n        snprintf(t, sizeof(t), \"plano_invalido:%s\", m);\n        copia(motivo, t, msz);\n        return false;\n    }\n    // Condicao de partida (spec 6.2 item 1): tensao e seguranca ok, senao NAO executa.\n    if ((_cfg.tem_tensao && !_in.tensao) || (_cfg.tem_seguranca && !_in.seguranca)) {\n        _motivo = M_CONDICAO_PARTIDA;\n        _evento(\"parado\", \"condicao_partida\");\n        copia(motivo, \"condicao_partida\", msz);\n        return false;\n    }\n    // Pivo ja' girando pelo painel (retorno de sentido ativo): nao parte por cima.\n    if ((_cfg.tem_gir_dir && _in.gir_dir) || (_cfg.tem_gir_esq && _in.gir_esq)) { copia(motivo, \"pivo_girando\", msz); return false; }\n\n    _plano = q;\n    _motivo = M_NENHUMA;\n    _alertas = 0;\n    _soma = 0; _contando = false;\n    _t_canhao_sem = 0; _q_pressao = _q_tensao = _q_lado = 0;\n    _t_ligar = now;\n    _out = Saidas();\n    _evento(\"ligar\", _plano.id);\n    _ir(PARTINDO);\n    if (_plano.com_agua) {\n        _out.bomba = true;                       // spec 6.2 item 2: BO1 e BO2 juntas\n        _out.valvula = _cfg.tem_valvula;\n        _passo = P_PRESSAO; _t_passo = now;\n        _evento(\"passo\", \"bomba_ligada\");\n    } else {\n        _acionarLado(now);                       // spec 6.3: sem agua nao liga bomba nem espera pressao\n    }\n    if (motivo && msz) motivo[0] = 0;\n    return true;\n}\n\nvoid Maquina::desligar(uint8_t motivo, uint32_t now) {\n    (void)now;\n    bool estava = _st != PARADO;\n    _out = Saidas();                             // spec 6.6: BO1..BO6 LOW, percentimetro 0\n    _passo = P_NENHUM;\n    _contando = false;\n    _t_canhao_sem = 0;\n    _alertas &= (uint8_t)~(A_FALHA_CANHAO | A_ERRO_POSICAO);\n    if (estava || motivo != M_COMANDO) _motivo = motivo;\n    if (estava) _evento(\"parado\", motivoNome(motivo));\n    _ir(PARADO);\n}\n\nbool Maquina::ajustarPercentimetro(int16_t pm, char* motivo, size_t msz) {\n    if (_st != GIRANDO) { copia(motivo, \"nao_girando\", msz); return false; }\n    if (!_plano.com_agua) { copia(motivo, \"sem_agua\", msz); return false; }\n    if (pm < 0 || pm > 1000) { copia(motivo, \"percentimetro\", msz); return false; }\n    _plano.pm = pm;\n    _out.perc_pm = pm;\n    _evento(\"passo\", \"percentimetro\");\n    if (motivo && msz) motivo[0] = 0;\n    return true;\n}\n\nbool Maquina::ajustarCanhao(bool ligado, bool tem_faixa, uint16_t desliga_em, uint16_t liga_em, uint32_t now, char* motivo, size_t msz) {\n    if (_st != GIRANDO) { copia(motivo, \"nao_girando\", msz); return false; }\n    if (!_plano.com_agua) { copia(motivo, \"sem_agua\", msz); return false; }\n    if (!_cfg.tem_canhao) { copia(motivo, \"sem_canhao\", msz); return false; }\n    if (tem_faixa && (desliga_em > 359 || liga_em > 359)) { copia(motivo, \"faixa\", msz); return false; }\n    _plano.canhao = ligado;\n    _plano.tem_faixa = tem_faixa;\n    _plano.desliga_em = desliga_em;\n    _plano.liga_em = liga_em;\n    _avaliarCanhao(now);                         // idempotente: pedir o estado atual = sucesso\n    if (motivo && msz) motivo[0] = 0;\n    return true;\n}\n\n// ---------------------------------------------------------------- sequencia\n\nvoid Maquina::_acionarLado(uint32_t now) {\n    _out.dir = _plano.dir == 'D';               // nunca os dois (BO3 xor BO4)\n    _out.esq = _plano.dir == 'E';\n    _passo = P_GIRO; _t_passo = now;\n    _evento(\"passo\", _plano.dir == 'D' ? \"girar_direita\" : \"girar_esquerda\");\n}\n\nvoid Maquina::_entrarGirando(uint32_t now) {\n    _passo = P_NENHUM;\n    _q_pressao = _q_tensao = _q_lado = 0;\n    _out.perc_pm = _plano.com_agua ? _plano.pm : 1000;   // percentimetro entra no loop\n    _ir(GIRANDO);\n    _evento(\"girando\", _plano.id);\n    // Referencia dos graus percorridos (spec 6.2 item 6): leitura recente vale; senao a proxima.\n    _soma = 0;\n    _contando = _tem_pos && (now - _t_pos) < _cfg.sem_posicao_ms;\n    _avaliarCanhao(now);                         // canhao na hora (sem esperar BI6)\n}\n\n// Dentro de [desliga_em, liga_em] o canhao fica OFF; faixa que passa pelo zero (ex.: 340..20).\nbool Maquina::_canhaoNaFaixaOff() const {\n    if (!_plano.tem_faixa || !_tem_pos) return false;\n    int a = (int)(_ang + 0.5f) % 360;\n    int d = _plano.desliga_em, l = _plano.liga_em;\n    if (d <= l) return a >= d && a <= l;\n    return a >= d || a <= l;\n}\n\nvoid Maquina::_avaliarCanhao(uint32_t now) {\n    bool quer = _st == GIRANDO && _plano.com_agua && _plano.canhao && _cfg.tem_canhao && !_canhaoNaFaixaOff();\n    if (_out.canhao != quer) {\n        _out.canhao = quer;\n        _t_canhao_sem = 0;\n        _evento(\"passo\", quer ? \"canhao_ligar\" : \"canhao_desligar\");\n    }\n    if (!quer) { _t_canhao_sem = 0; _alertas &= (uint8_t)~A_FALHA_CANHAO; }\n    (void)now;\n}\n\nvoid Maquina::tick(uint32_t now, const Entradas& in) {\n    _in = in;\n    if (_st == PARADO) return;\n\n    // Seguranca (BI5): 0 ou sem sinal -> desliga NA HORA (spec 6.4), em qualquer etapa\n    if (_cfg.tem_seguranca && !in.seguranca) { desligar(M_SEGURANCA, now); return; }\n    if (_cfg.tem_tensao && _queda(in.tensao, _q_tensao, _cfg.tol_tensao_ms, now)) { desligar(M_TENSAO, now); return; }\n    uint32_t dt = now - _t_passo;\n\n    if (_st == PARTINDO) {\n        if (_passo == P_PRESSAO) {\n            if (_cfg.tem_pressao ? in.pressao : dt >= _cfg.espera_pressao_ms) _acionarLado(now);\n            else if (_cfg.tem_pressao && dt >= _cfg.espera_pressao_ms) desligar(M_PRESSAO_NAO_SUBIU, now);\n        } else if (_passo == P_GIRO) {\n            if (!_temGir() || _gir()) _entrarGirando(now);          // confirmou: segue NA HORA\n            else if (dt >= _cfg.confirma_giro_ms) desligar(M_NAO_GIROU, now);\n        }\n        return;\n    }\n\n    // GIRANDO\n    if (_plano.com_agua && _cfg.tem_pressao && _queda(in.pressao, _q_pressao, _cfg.tol_pressao_ms, now)) { desligar(M_QUEDA_PRESSAO, now); return; }\n    if (_temGir() && _queda(_gir(), _q_lado, _cfg.tol_lado_ms, now)) { desligar(M_LADO_CAIU, now); return; }\n    if (_plano.parada == POR_DURACAO && (now - _t_ligar) >= _plano.duracao_s * 1000UL) { desligar(M_CONCLUIDA, now); return; }\n\n    // Encoder sem leitura: mantem a operacao e sinaliza (spec 6.4); o operador decide.\n    if (_plano.parada == POR_GRAUS || _plano.tem_faixa) {\n        uint32_t ult = (_tem_pos && (int32_t)(_t_pos - _t_ligar) > 0) ? _t_pos : _t_ligar;\n        if ((now - ult) >= _cfg.sem_posicao_ms) _alertas |= A_ERRO_POSICAO;\n    }\n    // Canhao: ligado e a BI6 nao confirma -> alerta (nao para)\n    if (_out.canhao && _cfg.tem_canhao_st) {\n        if (in.canhao) { _t_canhao_sem = 0; _alertas &= (uint8_t)~A_FALHA_CANHAO; }\n        else {\n            if (!_t_canhao_sem) _t_canhao_sem = now ? now : 1;\n            if ((now - _t_canhao_sem) >= _cfg.confirma_canhao_ms) _alertas |= A_FALHA_CANHAO;\n        }\n    }\n}\n\nvoid Maquina::posicao(float g, uint32_t now) {\n    if (!(g >= -720.0f && g <= 720.0f)) return;            // NaN/lixo\n    g = norm360(g);\n    if (!_tem_pos) {\n        _tem_pos = true; _ang = g; _ang_ref = g; _t_pos = now; _t_ang_mudou = now;\n    } else {\n        float d = dif180(_ang, g);\n        bool salto = absf(d) > SALTO_MAX_GRAUS;\n        if (!salto && absf(dif180(_ang_ref, g)) >= MUDOU_GRAUS) { _t_ang_mudou = now; _ang_mudou_ok = true; _ang_ref = g; }\n        if (salto) _ang_ref = g;\n        // Soma COM SINAL (o vai-e-volta de 1 grau do encoder se cancela); percorrido = |soma|.\n        if (_contando && !salto && _st == GIRANDO) _soma += d;\n        _ang = g; _t_pos = now;\n    }\n    _alertas &= (uint8_t)~A_ERRO_POSICAO;\n    if (_st != GIRANDO) return;\n    if (!_contando) { _contando = true; _soma = 0; }        // 1a leitura depois de girar = referencia\n    if (_plano.parada == POR_GRAUS && absf(_soma) >= (float)_plano.graus) { desligar(M_CONCLUIDA, now); return; }\n    _avaliarCanhao(now);                                     // faixa do canhao a cada posicao\n}\n\n} // namespace pivo\n",
    "include/pivo.h": "// pivo.h — pivo na TON (glue gerado; logica na lib pivo_local). docs/IOT-PIVO-TON-LOCAL.md\n#ifndef PIVO_H\n#define PIVO_H\n#include <Arduino.h>\n\ntypedef void (*pivo_publish_fn)(const char* subtopic, const char* payload);\n\nvoid pivo_init();                          // NVS (io/tempos/encoder); reles do pivo desligados\nvoid pivo_tick();                          // SO' controle: le BI, roda a maquina, aplica BO (sem radio) — chamar logo apos inputs_scan()\nvoid pivo_loop(pivo_publish_fn publish);   // pivo_tick() + publicacao (status/eventos)\nbool pivo_ocioso();                        // parado: libera OTA e reinicio\nvoid pivo_encoder_bruto(float bruto);      // leitura nova do encoder (contagem crua do Modbus)\n// Calibracao (NEXON-103): \"pivo encler\" pede 5 leituras seguidas por pivo_encoder_amostrar(), que o\n// modbus_meter.cpp define quando ha' Encoder no RS485 (true = leitura boa, ja' entregue acima).\nvoid pivo_publicar_agora();                // forca o status no proximo loop\nvoid pivo_publicar(pivo_publish_fn publish); // publica o status AGORA (resposta ao POLL do LoRa)\nvoid pivo_so_no_poll(bool so_poll);        // satelite mestre-puxa: status so' na resposta ao POLL\n// \"pivo ...\" (Serial / <BASE>/cmd). -1 = nao e' comando do pivo; 0 = recusado; 1 = ok. msg = resultado curto.\nint  pivo_cmd(const String& cmd, char* msg, size_t msg_sz);\n#endif\n",
    "src/pivo.cpp": "// pivo.cpp — glue gerado: PIVO na TON (sequencia local, sem depender de internet).\n// A logica (ligar/irrigar/paradas/desligar/seguranca) esta em pivo_local.cpp (lib pura,\n// testada no host). Aqui: BI com polaridade por papel, BO por papel, ciclo do percentimetro,\n// encoder -> angulo, NVS, comandos \"pivo ...\" e publicacao (status + eventos).\n// Fonte canonica: AupusNexOn/firmware-libs/pivo_local/glue/. docs/IOT-PIVO-TON-LOCAL.md\n//\n// Comandos (minusculos; Serial ou <BASE>/cmd, tambem pelo LoRa):\n//   pivo io <bo1..bo6> <bi1..bi6> <inv>   papeis BO: bomba valvula dir esq perc canhao\n//                                         papeis BI: pressao tensao gir_dir gir_esq seguranca canhao\n//                                         0 = nao ligado; inv = 6 digitos 0/1 (1 = BI ativa em baixo)\n//   pivo tempos <espera_pressao> <confirma_giro> <confirma_canhao> <tol_pressao> <tol_tensao> <tol_lado> <sem_posicao> <janela_giro> <ciclo_perc>  (s)\n//   pivo enc <resolucao> <inv 0|1> <zero_graus>      resolucao 0 = sem encoder (o NexON manda 360 0 0: valor BRUTO)\n//   pivo ligar <id> <d|e> <agua 0|1> <permil> <canhao 0|1> <g|t> <valor> [f <desliga_em> <liga_em>]\n//        g = graus a percorrer (voltas = 360 x n, no NexON) · t = segundos (provisorio, pivo sem encoder)\n//        f = faixa do canhao (bruto 0..359): dentro de [desliga_em, liga_em] o canhao fica OFF\n//   pivo cfg <BOs 6 dig> <BIs 6 dig> <inv 6 dig> <9 tempos> <resolucao>   (tudo de uma vez; o ack do status traz k<CRC16>)\n//   pivo desligar | pivo perc <permil> | pivo canhao <0|1> [f <desliga_em> <liga_em>] | pivo status | pivo mostrar\n// Segurança (BI5): normal = 1 (spec); 0 ou sem sinal = atuou.\n// Compatibilidade (sequencia ainda no servidor, ate' a Fase 3): com a sequencia local PARADA,\n//   perc <bo> <permil> <ciclo_s> <mascara> | perc off   (igual ao firmware anterior; mascara = DINs\n//   de \"girando\", bit0 = DIN1: o ciclo so' roda com alguma delas em 1). Nao fica na NVS.\n#include \"pivo.h\"\n#include \"config.h\"\n#include \"pivo_local.h\"\n#include \"inputs.h\"\n#include \"relays.h\"\n#include <Preferences.h>\n#include <esp_system.h>\n#include <esp_attr.h>\n#include <math.h>\n#include <string.h>\n#include <stdlib.h>\n\nusing namespace pivo;\n\nextern uint32_t diag_i2c_resets;   // relays.cpp: recuperacoes do barramento I2C dos reles\n\n// Leitura imediata do encoder (gerada em modbus_meter.cpp quando ha' Encoder no RS485 desta TON).\n// Fraca: firmware sem encoder nao define, e \"pivo encler\" responde pivo_sem_encoder.\nextern bool pivo_encoder_amostrar() __attribute__((weak));\n\nenum { BO_BOMBA = 0, BO_VALVULA, BO_DIR, BO_ESQ, BO_PERC, BO_CANHAO };\nenum { BI_PRESSAO = 0, BI_TENSAO, BI_GIR_DIR, BI_GIR_ESQ, BI_SEGURANCA, BI_CANHAO };\n#define PIVO_IO_MAX 8\n\n// ---- configuracao (NVS \"pivo\"); sai da gravacao com o I/O PADRAO (BO01-06/BI01-06, ativo em alto):\n// a TON ja' liga/desliga sozinha logo apos gravar. O NexON sobrescreve com \"pivo io\" se o mapa for outro.\nstatic uint8_t  _bo[6] = {1, 2, 3, 4, 5, 6};\nstatic uint8_t  _bi[6] = {1, 2, 3, 4, 5, 6};\nstatic uint8_t  _inv = 0;                // bit k = BI do papel k ativa em baixo\n// s: espera_pressao, confirma_giro, confirma_canhao, tol_pressao, tol_tensao, tol_lado, sem_posicao, janela_giro, ciclo_perc\n#define PIVO_NTP 9\nstatic uint32_t _tp[PIVO_NTP] = {60, 30, 5, 0, 0, 0, 30, 600, 60};   // tolerancias 0 = queda desliga na hora\nstatic uint32_t _enc_res = 0;            // 0 = sem encoder\nstatic bool     _enc_inv = false;\nstatic float    _enc_zero = 0;\nstatic bool     _cfg_ok = true;\nstatic uint16_t _cfg_ck = 0;             // CRC16 (Modbus) dos argumentos do ultimo \"pivo cfg\" aplicado; 0 = desconhecido\n\n// CRC16 Modbus (o NexON calcula igual sobre o mesmo texto e so' reenvia a config se mudou)\nstatic uint16_t _crc16(const char* s) {\n    uint16_t crc = 0xFFFF;\n    for (; *s; s++) {\n        crc ^= (uint8_t)*s;\n        for (int i = 0; i < 8; i++) crc = (crc & 1) ? (uint16_t)((crc >> 1) ^ 0xA001) : (uint16_t)(crc >> 1);\n    }\n    return crc;\n}\n\n// ---- estado do glue\nstatic Maquina* _m = nullptr;\nstatic int8_t   _apl[6] = {-1, -1, -1, -1, -1, -1};   // ultimo valor escrito por papel de BO\nstatic unsigned long _perc_ini = 0;\nstatic int16_t  _perc_pm_ciclo = -1;\nstatic bool     _perc_on = false;\nstatic volatile bool _enc_novo = false;\nstatic float    _enc_bruto = 0;\nstatic bool     _pub_agora = true;\nstatic unsigned long _ult_pub = 0;\nstatic uint8_t  _bi_ant = 0xFF;\nstatic bool     _ativo_nvs = false;\n// Satelite LoRa mestre-puxa: frame espontaneo colide com o POLL do gateway (e com as\n// entradas, que mudam no mesmo instante). O status vai so' na resposta ao POLL.\nstatic bool     _so_poll = false;\nstatic unsigned long _reafirma_ms = 0;   // ultima reafirmacao das saidas do pivo\nstatic uint8_t  _bi_sem_atual = 0;       // entradas semanticas do ultimo pivo_tick()\n// Satelite: mudanca de ESTADO (parado/ligando/irrigando/desligando) vai na hora (1 frame) + 1 repeticao\n// em 8 s (o 1o pode colidir). Rara: nao satura o radio como os eventos de cada passo.\nstatic int8_t   _e_pub = -1;             // ultimo estado publicado espontaneamente\nstatic unsigned long _e_reforco_ms = 0;  // 0 = sem repeticao pendente\n// percentimetro LEGADO (comando \"perc\" do servidor), so' com a sequencia local parada\nstatic uint8_t  _leg_bo = 0;\nstatic int16_t  _leg_pm = -1;            // -1 = desligado\nstatic uint32_t _leg_ciclo_ms = 60000UL;\nstatic uint8_t  _leg_mask = 0;\nstatic unsigned long _leg_ini = 0;\nstatic int8_t   _leg_saida = -1;\n\n// ---- retomada apos reinicio por WATCHDOG (spec 6.7) ----\n// A ordem (Plano) e o andamento (graus percorridos a cada 10 graus; tempo a cada 60 s no provisorio\n// sem encoder) ficam na NVS. Reinicio por watchdog: refaz a partida inteira com o que falta. Outra causa\n// (energia, tensao, reset manual): nao retoma (\"reinicio da slave\"). 3 watchdogs em 1 h: nao retoma\n// mais, tudo desligado, alerta \"reinicios repetidos\". A janela de 1 h conta o tempo LIGADO acumulado\n// na RTC (sobrevive a reinicio por software; zera em queda de energia) — nao depende de relogio.\n#define PIVO_WD_MAGIC 0x50574454UL\nRTC_NOINIT_ATTR static uint32_t _rtcWdMagic;\nRTC_NOINIT_ATTR static uint32_t _rtcWdCount;\nRTC_NOINIT_ATTR static uint32_t _rtcWdFirst;   // tempo acumulado no 1o watchdog da janela\nRTC_NOINIT_ATTR static uint32_t _rtcAcc;       // tempo ligado acumulado (ms) ate' agora\nstatic uint32_t _accBase = 0;\nstatic bool     _retomar = false;\nstatic unsigned long _retomar_em = 0;\nstatic Plano    _plano_salvo;\nstatic float    _gp_salvo = 0;                 // graus ja' percorridos gravados na NVS\nstatic uint32_t _ms_salvo = 0;                 // tempo ja' girado gravado (provisorio, por duracao)\nstatic unsigned long _ult_ms_salvo = 0;\n\n// ---- fila de eventos (o Ouvinte e' chamado dentro do tick; publica no loop)\nstruct EvPivo { char t[12]; char x[24]; char id[ID_LEN]; char e[12]; };\nstatic EvPivo  _evq[12];\nstatic uint8_t _evh = 0, _evn = 0;\nstatic void _evPush(const char* t, const char* x) {\n    EvPivo& v = _evq[(_evh + _evn) % 12];\n    if (_evn == 12) _evh = (_evh + 1) % 12; else _evn++;   // cheia: descarta o mais velho\n    strncpy(v.t, t, sizeof(v.t) - 1); v.t[sizeof(v.t) - 1] = 0;\n    strncpy(v.x, x ? x : \"\", sizeof(v.x) - 1); v.x[sizeof(v.x) - 1] = 0;\n    strncpy(v.id, _m ? _m->plano().id : \"\", sizeof(v.id) - 1); v.id[sizeof(v.id) - 1] = 0;\n    strncpy(v.e, _m ? estadoNome(_m->estado()) : \"\", sizeof(v.e) - 1); v.e[sizeof(v.e) - 1] = 0;\n}\n\nstatic void _salvarAtivo(bool ativo) {\n    if (ativo == _ativo_nvs) return;\n    _ativo_nvs = ativo;\n    Preferences pr;\n    if (!pr.begin(\"pivo\", false)) return;\n    pr.putBool(\"at\", ativo);\n    if (ativo && _m) {\n        pr.putString(\"id\", _m->plano().id);\n        pr.putBytes(\"pl\", &_m->plano(), sizeof(Plano));   // a ordem inteira (retomada apos watchdog)\n        pr.putFloat(\"gp\", 0); pr.putUInt(\"ms\", 0);\n        _gp_salvo = 0; _ms_salvo = 0; _ult_ms_salvo = millis();\n    }\n    pr.end();\n}\n\n// Andamento: graus a cada 10 (poupa a flash, spec 6.7); tempo a cada 60 s (provisorio sem encoder).\nstatic void _salvarAndamento(unsigned long now) {\n    if (!_m || _m->estado() != GIRANDO) return;\n    float gp = _m->percorrido();\n    bool porGraus = gp - _gp_salvo >= 10.0f;\n    bool porTempo = _m->plano().parada == POR_DURACAO && now - _ult_ms_salvo >= 60000UL;\n    if (!porGraus && !porTempo) return;\n    Preferences pr;\n    if (!pr.begin(\"pivo\", false)) return;\n    if (porGraus) { pr.putFloat(\"gp\", gp); _gp_salvo = gp; }\n    if (porTempo) { _ms_salvo = _m->tempoGirandoMs(now); pr.putUInt(\"ms\", _ms_salvo); _ult_ms_salvo = now; }\n    pr.end();\n}\n\nstruct OuvinteGlue : Ouvinte {\n    void aoEvento(const char* tipo, const char* det) override {\n        Serial.printf(\"[PIVO] %s %s\\n\", tipo, det ? det : \"\");\n        _evPush(tipo, det);\n        _pub_agora = true;\n    }\n    void aoMudarEstado(Estado de, Estado para) override {\n        Serial.printf(\"[PIVO] %s -> %s\\n\", estadoNome(de), estadoNome(para));\n        _salvarAtivo(para != PARADO);\n        _pub_agora = true;\n    }\n};\nstatic OuvinteGlue _ouv;\n\nstatic Config _montarConfig() {\n    Config c;\n    c.tem_valvula   = _bo[BO_VALVULA] != 0;\n    c.tem_canhao    = _bo[BO_CANHAO] != 0;\n    c.tem_pressao   = _bi[BI_PRESSAO] != 0;\n    c.tem_tensao    = _bi[BI_TENSAO] != 0;\n    c.tem_gir_dir   = _bi[BI_GIR_DIR] != 0;\n    c.tem_gir_esq   = _bi[BI_GIR_ESQ] != 0;\n    c.tem_seguranca = _bi[BI_SEGURANCA] != 0;\n    c.tem_canhao_st = _bi[BI_CANHAO] != 0;\n    c.espera_pressao_ms  = _tp[0] * 1000UL;\n    c.confirma_giro_ms   = _tp[1] * 1000UL;\n    c.confirma_canhao_ms = _tp[2] * 1000UL;\n    c.tol_pressao_ms     = _tp[3] * 1000UL;\n    c.tol_tensao_ms      = _tp[4] * 1000UL;\n    c.tol_lado_ms        = _tp[5] * 1000UL;\n    c.sem_posicao_ms     = _tp[6] * 1000UL;\n    c.janela_giro_ms     = _tp[7] * 1000UL;\n    return c;\n}\n\nstatic void _salvarCfg() {\n    Preferences pr;\n    if (!pr.begin(\"pivo\", false)) return;\n    pr.putBytes(\"bo\", _bo, sizeof(_bo));\n    pr.putBytes(\"bi\", _bi, sizeof(_bi));\n    pr.putUChar(\"inv\", _inv);\n    pr.putBytes(\"tp2\", _tp, sizeof(_tp));   // \"tp2\": formato de 12/11 (o \"tp\" antigo e' ignorado)\n    pr.putUInt(\"er\", _enc_res);\n    pr.putBool(\"ei\", _enc_inv);\n    pr.putFloat(\"ez\", _enc_zero);\n    pr.putBool(\"ok\", _cfg_ok);\n    pr.putUShort(\"ck\", _cfg_ck);\n    pr.end();\n}\n\nvoid pivo_init() {\n    Preferences pr;\n    char id[ID_LEN] = \"\";\n    bool estava = false;\n    bool temPlano = false;\n    if (pr.begin(\"pivo\", true)) {\n        if (pr.getBytesLength(\"pl\") == sizeof(Plano)) { pr.getBytes(\"pl\", &_plano_salvo, sizeof(Plano)); temPlano = true; }\n        _gp_salvo = pr.getFloat(\"gp\", 0);\n        _ms_salvo = pr.getUInt(\"ms\", 0);\n        if (pr.getBytesLength(\"bo\") == sizeof(_bo)) pr.getBytes(\"bo\", _bo, sizeof(_bo));\n        if (pr.getBytesLength(\"bi\") == sizeof(_bi)) pr.getBytes(\"bi\", _bi, sizeof(_bi));\n        _inv = pr.getUChar(\"inv\", 0);\n        if (pr.getBytesLength(\"tp2\") == sizeof(_tp)) pr.getBytes(\"tp2\", _tp, sizeof(_tp));\n        _enc_res = pr.getUInt(\"er\", 0);\n        _enc_inv = pr.getBool(\"ei\", false);\n        _enc_zero = pr.getFloat(\"ez\", 0);\n        _cfg_ok = pr.getBool(\"ok\", true);\n        _cfg_ck = pr.getUShort(\"ck\", 0);\n        estava = pr.getBool(\"at\", false);\n        pr.getString(\"id\", id, sizeof(id));\n        pr.end();\n    }\n    for (int k = 0; k < 6; k++) { if (_bo[k] > PIVO_IO_MAX) _bo[k] = 0; if (_bi[k] > PIVO_IO_MAX) _bi[k] = 0; }\n    static Maquina m(_montarConfig(), &_ouv);\n    _m = &m;\n    // Reles do pivo ja' saem desligados (RELAYS_RESTORE_ON_SW_RESET = 0): reinicio = pivo parado.\n    // Contadores de watchdog na RTC: lixo depois de queda de energia -> zera.\n    if (_rtcWdMagic != PIVO_WD_MAGIC) { _rtcWdMagic = PIVO_WD_MAGIC; _rtcWdCount = 0; _rtcWdFirst = 0; _rtcAcc = 0; }\n    _accBase = _rtcAcc;\n    esp_reset_reason_t rr = esp_reset_reason();\n    bool porWatchdog = rr == ESP_RST_TASK_WDT || rr == ESP_RST_INT_WDT || rr == ESP_RST_WDT;\n    if (porWatchdog) {\n        if (_rtcWdCount == 0 || _accBase - _rtcWdFirst > 3600000UL) { _rtcWdCount = 1; _rtcWdFirst = _accBase; }\n        else _rtcWdCount++;\n    }\n    if (estava) {\n        _m->marcarMotivo(M_REINICIO);\n        if (porWatchdog && temPlano && _rtcWdCount < 3) {\n            // Retoma: a partida inteira de novo, com o que falta (spec 6.7). Espera as entradas assentarem.\n            if (_plano_salvo.parada == POR_GRAUS) {\n                uint32_t feito = (uint32_t)lroundf(_gp_salvo);\n                _plano_salvo.graus = _plano_salvo.graus > feito + 1 ? _plano_salvo.graus - feito : 1;\n            } else {\n                uint32_t feito_s = _ms_salvo / 1000UL;\n                _plano_salvo.duracao_s = _plano_salvo.duracao_s > feito_s + 60 ? _plano_salvo.duracao_s - feito_s : 60;\n            }\n            _retomar = true;\n            _retomar_em = millis() + 5000UL;\n            Serial.printf(\"[PIVO] reinicio por WATCHDOG (%lu na ultima hora): retomando a ordem %s em 5 s\\n\", (unsigned long)_rtcWdCount, _plano_salvo.id);\n        } else if (porWatchdog && _rtcWdCount >= 3) {\n            _m->marcarAlerta(A_REINICIOS);\n            Serial.println(\"[PIVO] 3 reinicios por watchdog em 1 h: NAO retoma (reinicios repetidos)\");\n        }\n        _evPush(\"parado\", \"reinicio_slave\");\n        strncpy(_evq[(_evh + _evn - 1) % 12].id, id, ID_LEN - 1);\n        _ativo_nvs = true;\n        _salvarAtivo(false);\n    }\n    Serial.printf(\"[PIVO] init: cfg=%d BO %u/%u/%u/%u/%u/%u BI %u/%u/%u/%u/%u/%u inv=0x%02X enc=%lu%s\\n\",\n        _cfg_ok, _bo[0], _bo[1], _bo[2], _bo[3], _bo[4], _bo[5], _bi[0], _bi[1], _bi[2], _bi[3], _bi[4], _bi[5],\n        _inv, (unsigned long)_enc_res, estava ? \" (estava irrigando: reinicio)\" : \"\");\n}\n\nbool pivo_ocioso() { return !_m || _m->estado() == PARADO; }\nvoid pivo_encoder_bruto(float bruto) { _enc_bruto = bruto; _enc_novo = true; }\nvoid pivo_publicar_agora() { _pub_agora = true; _ult_pub = 0; }\nvoid pivo_so_no_poll(bool so_poll) { _so_poll = so_poll; }\n\nstatic bool _biPapel(uint8_t st, int papel) {\n    uint8_t n = _bi[papel];\n    if (!n) return false;\n    bool v = (st >> (n - 1)) & 1;\n    return (_inv >> papel) & 1 ? !v : v;\n}\n\nstatic void _setBo(int papel, bool on) {\n    uint8_t n = _bo[papel];\n    if (!n) return;\n    int8_t v = on ? 1 : 0;\n    if (_apl[papel] == v) return;\n    _apl[papel] = v;\n    relay_set(n, on);\n}\n\n// Ciclo do percentimetro: a BO anda permil/1000 do ciclo. So' roda com o lado confirmado\n// (BI girando do lado, ou o comando do lado quando nao ha BI). Troca de % vale no proximo ciclo.\nstatic bool _percSaida(int16_t pm, bool ladoOk, unsigned long now) {\n    if (pm < 0) { _perc_ini = 0; _perc_pm_ciclo = -1; return false; }\n    if (!ladoOk) { _perc_ini = 0; return false; }\n    uint32_t ciclo = _tp[8] * 1000UL;\n    if (!_perc_ini || now - _perc_ini >= ciclo) { _perc_ini = now ? now : 1; _perc_pm_ciclo = pm; }\n    uint32_t on_ms = (uint32_t)(((uint64_t)ciclo * (uint32_t)_perc_pm_ciclo) / 1000ULL);\n    return (now - _perc_ini) < on_ms;\n}\n\nstatic float _anguloDe(float bruto) {\n    double r = fmod((double)bruto, (double)_enc_res);\n    if (r < 0) r += _enc_res;\n    float g = (float)(r * 360.0 / (double)_enc_res);\n    if (_enc_inv) g = 360.0f - g;\n    g += _enc_zero;\n    while (g >= 360.0f) g -= 360.0f;\n    while (g < 0.0f) g += 360.0f;\n    return g;\n}\n\nstatic void _publicarStatus(pivo_publish_fn pub) {\n    const Saidas& o = _m->saidas();\n    const Entradas& in = _m->entradas();\n    // Status (spec 7.3), compacto: o satelite LoRa aceita ate' ~120 B de conteudo.\n    //   o = id da ordem · i = entradas (bit0 BI1 pressao, 1 BI2 tensao, 2 BI3 dir, 3 BI4 esq, 4 BI5 seguranca, 5 BI6 canhao)\n    //   et = etapa (0 parado, 1 aguardando pressao/giro, 2 girando) · p = passo da partida (1 pressao, 2 giro)\n    //   an = angulo BRUTO do encoder (null = sem leitura) · gp = graus percorridos · al = graus da parada\n    //   pm = percentimetro em permil (-1 = desligado) · mo = motivo da ultima parada · at = alertas\n    //   (bit0 erro de posicao, 1 falha no canhao, 2 reinicios repetidos) · bo = saidas (bit0 bomba .. 5 canhao, 6 girando)\n    uint8_t bi = (in.pressao ? 1 : 0) | (in.tensao ? 2 : 0) | (in.gir_dir ? 4 : 0) | (in.gir_esq ? 8 : 0) | (in.seguranca ? 16 : 0) | (in.canhao ? 32 : 0);\n    uint8_t bo = (o.bomba ? 1 : 0) | (o.valvula ? 2 : 0) | (o.dir ? 4 : 0) | (o.esq ? 8 : 0) | (_perc_on ? 16 : 0) | (o.canhao ? 32 : 0);\n    if (_m->girando(millis())) bo |= 64;\n    char an[8];\n    if (_m->temPosicao()) snprintf(an, sizeof(an), \"%ld\", (long)lroundf(_m->angulo())); else strcpy(an, \"null\");\n    const Plano& p = _m->plano();\n    char payload[160];\n    snprintf(payload, sizeof(payload),\n        \"{\\\"o\\\":\\\"%s\\\",\\\"i\\\":%u,\\\"et\\\":%d,\\\"p\\\":%d,\\\"an\\\":%s,\\\"gp\\\":%ld,\\\"al\\\":%lu,\\\"pm\\\":%d,\\\"mo\\\":%u,\\\"at\\\":%u,\\\"d\\\":\\\"%c\\\",\\\"a\\\":%d,\\\"bo\\\":%u}\",\n        _m->estado() == PARADO ? \"\" : p.id, bi, (int)_m->estado(), (int)_m->passo(), an, (long)lroundf(_m->percorrido()),\n        (unsigned long)_m->alvo(), (int)o.perc_pm, (unsigned)_m->motivo(), (unsigned)_m->alertas(), p.dir, p.com_agua ? 1 : 0, bo);\n    if (pub) pub(\"pivo\", payload);\n}\n\nvoid pivo_publicar(pivo_publish_fn publish) {\n    if (!_m || !publish) return;\n    _pub_agora = false;\n    _ult_pub = millis() ? millis() : 1;\n    _publicarStatus(publish);\n    _e_pub = (int8_t)_m->estado();   // o POLL ja' levou este estado\n}\n\n// Controle do pivo: entradas -> maquina -> saidas. Sem radio/MQTT: e' chamado logo apos o\n// inputs_scan() (a BO bate no mesmo ciclo em que a BI mudou) e de novo no pivo_loop().\nvoid pivo_tick() {\n    if (!_m) return;\n    unsigned long now = millis();\n    _rtcAcc = _accBase + (uint32_t)now;              // tempo ligado acumulado (janela dos watchdogs)\n    if (_retomar && (long)(now - _retomar_em) >= 0) {\n        _retomar = false;\n        char mot[40];\n        if (_m->ligar(_plano_salvo, now, mot, sizeof(mot))) Serial.println(\"[PIVO] ordem retomada apos watchdog\");\n        else { _m->marcarMotivo(M_REINICIO); Serial.printf(\"[PIVO] retomada recusada (%s)\\n\", mot); }\n    }\n    uint8_t st = inputs_get_state();\n    Entradas in;\n    in.pressao     = _biPapel(st, BI_PRESSAO);\n    in.tensao      = _biPapel(st, BI_TENSAO);\n    in.gir_dir     = _biPapel(st, BI_GIR_DIR);\n    in.gir_esq     = _biPapel(st, BI_GIR_ESQ);\n    in.seguranca   = _biPapel(st, BI_SEGURANCA);   // 1 = ok (spec); 0 ou sem sinal = atuou\n    in.canhao      = _biPapel(st, BI_CANHAO);\n\n    if (_enc_novo) {\n        _enc_novo = false;\n        if (_enc_res) _m->posicao(_anguloDe(_enc_bruto), now);\n    }\n    _m->tick(now, in);\n    _salvarAndamento(now);\n\n    // Expansor de reles sem controle (I2C): o rele pode estar preso em qualquer estado. Pivo\n    // ligado -> desliga com falha; parado -> recusa ligar (pivo_cmd). Nao da' para confiar na saida.\n    if (relays_io_fault()) {\n        if (_m->estado() != PARADO) {\n            _m->desligar(M_FALHA_RELES, now);\n            Serial.println(\"[PIVO] FALHA: reles sem controle (I2C) - desligando o pivo\");\n        }\n    }\n    // Reafirma TODAS as saidas do pivo a cada 1 s (nao confia no cache: escrita perdida ou rele\n    // mexido por fora volta ao estado que a sequencia quer em ate' 1 s).\n    if (now - _reafirma_ms >= 1000UL) {\n        _reafirma_ms = now ? now : 1;\n        for (int k = 0; k < 6; k++) _apl[k] = -1;\n    }\n    // Saidas (mantidas) + ciclo do percentimetro. Ordem: DESLIGA antes de ligar, e os dois\n    // sentidos nunca em alto juntos (intertravamento por software alem da lib).\n    const Saidas& o = _m->saidas();\n    bool qDir = o.dir, qEsq = o.esq;\n    if (qDir && qEsq) { qDir = false; qEsq = false; Serial.println(\"[PIVO] BUG: dir e esq pedidos juntos - os dois em OFF\"); }\n    if (!qDir) _setBo(BO_DIR, false);\n    if (!qEsq) _setBo(BO_ESQ, false);\n    if (!o.bomba) _setBo(BO_BOMBA, false);\n    if (!o.valvula) _setBo(BO_VALVULA, false);\n    if (!o.canhao) _setBo(BO_CANHAO, false);\n    if (qDir) _setBo(BO_DIR, true);   // o oposto ja' foi para OFF acima (e e' reafirmado a cada 1 s)\n    if (qEsq) _setBo(BO_ESQ, true);\n    if (o.bomba) _setBo(BO_BOMBA, true);\n    if (o.valvula) _setBo(BO_VALVULA, true);\n    if (o.canhao) _setBo(BO_CANHAO, true);\n    bool ladoOk = (o.dir && (!_bi[BI_GIR_DIR] || in.gir_dir)) || (o.esq && (!_bi[BI_GIR_ESQ] || in.gir_esq));\n    if (_m->estado() == PARADO && _leg_pm >= 0 && _leg_bo) {\n        // Percentimetro legado (servidor): ciclo na BO pedida, so' com DIN de girando em 1.\n        bool gir = !_leg_mask || (st & _leg_mask);\n        bool on = false;\n        if (!gir) _leg_ini = 0;\n        else {\n            if (!_leg_ini || now - _leg_ini >= _leg_ciclo_ms) _leg_ini = now ? now : 1;\n            on = (now - _leg_ini) < (uint32_t)(((uint64_t)_leg_ciclo_ms * (uint32_t)_leg_pm) / 1000ULL);\n        }\n        if (_leg_saida != (on ? 1 : 0)) { _leg_saida = on ? 1 : 0; relay_set(_leg_bo, on); }\n        _perc_on = on;\n        for (int k = 0; k < 6; k++) if (_bo[k] == _leg_bo) _apl[k] = -1;   // a sequencia local reescreve ao assumir\n    } else {\n        if (_leg_pm >= 0 && _m->estado() != PARADO) { _leg_pm = -1; _leg_saida = -1; }   // sequencia local assumiu\n        _perc_on = _percSaida(o.perc_pm, ladoOk, now);\n        _setBo(BO_PERC, _perc_on);\n    }\n    _bi_sem_atual = (in.pressao ? 1 : 0) | (in.tensao ? 2 : 0) | (in.gir_dir ? 4 : 0) | (in.gir_esq ? 8 : 0) | (in.seguranca ? 16 : 0) | (in.canhao ? 32 : 0);\n}\n\nvoid pivo_loop(pivo_publish_fn publish) {\n    if (!_m) return;\n    pivo_tick();\n    unsigned long now = millis();\n\n    // Publicacao: eventos na hora; status na mudanca (min 1 s) e a cada 30 s ligado / 60 s parado\n    if (_bi_sem_atual != _bi_ant) { _bi_ant = _bi_sem_atual; _pub_agora = true; }\n    // Satelite LoRa: eventos NAO vao pelo radio (cada frame trava o loop ~0,5-0,8 s esperando o\n    // radio e ocupa o canal dos comandos). Estado/passo/falha vao no status do POLL e no ack do\n    // \"pivo status\". Descarta a fila.\n    if (_so_poll) _evn = 0;\n    while (_evn && publish) {\n        EvPivo& v = _evq[_evh];\n        char ev[128];\n        snprintf(ev, sizeof(ev), \"{\\\"t\\\":\\\"%s\\\",\\\"x\\\":\\\"%s\\\",\\\"e\\\":\\\"%s\\\",\\\"id\\\":\\\"%s\\\"}\", v.t, v.x, v.e, v.id);\n        publish(\"pivo/evento\", ev);\n        _evh = (_evh + 1) % 12; _evn--;\n    }\n    unsigned long periodo = _m->estado() == PARADO ? 60000UL : 30000UL;\n    if (_so_poll) {\n        // satelite mestre-puxa: status no POLL; so' a MUDANCA DE ESTADO sai na hora\n        int8_t e = (int8_t)_m->estado();\n        if (_e_pub < 0) _e_pub = e;                        // boot: o 1o POLL leva o estado\n        if (e != _e_pub && publish) {\n            _e_pub = e;\n            _publicarStatus(publish);\n            _e_reforco_ms = now + 8000UL; if (!_e_reforco_ms) _e_reforco_ms = 1;\n        } else if (_e_reforco_ms && (long)(now - _e_reforco_ms) >= 0 && publish) {\n            _e_reforco_ms = 0;\n            _publicarStatus(publish);\n        }\n        return;\n    }\n    if ((_pub_agora && now - _ult_pub >= 1000UL) || !_ult_pub || now - _ult_pub >= periodo) {\n        _pub_agora = false;\n        _ult_pub = now ? now : 1;\n        _publicarStatus(publish);\n    }\n}\n\n// ---------------------------------------------------------------- comandos\n\nstatic int _ok(char* msg, size_t sz, const char* m) { snprintf(msg, sz, \"%s\", m); return 1; }\nstatic int _erro(char* msg, size_t sz, const char* m) { snprintf(msg, sz, \"%s\", m); return 0; }\n\nstatic int _cmdLigar(char* args, char* msg, size_t sz) {\n    if (!_cfg_ok) return _erro(msg, sz, \"pivo_sem_config\");\n    if (relays_io_fault()) return _erro(msg, sz, \"pivo_falha_reles\");\n    Plano p;\n    char* sv = nullptr;\n    char* tok = strtok_r(args, \" \", &sv);\n    if (!tok) return _erro(msg, sz, \"pivo_ligar_invalido\");\n    strncpy(p.id, tok, ID_LEN - 1);\n    const char* d = strtok_r(nullptr, \" \", &sv);\n    const char* ag = strtok_r(nullptr, \" \", &sv);\n    const char* pm = strtok_r(nullptr, \" \", &sv);\n    const char* cn = strtok_r(nullptr, \" \", &sv);\n    const char* pt = strtok_r(nullptr, \" \", &sv);\n    const char* pv = strtok_r(nullptr, \" \", &sv);\n    if (!d || !ag || !pm || !cn || !pt || !pv) return _erro(msg, sz, \"pivo_ligar_invalido\");\n    p.dir = (d[0] == 'e') ? 'E' : (d[0] == 'd') ? 'D' : '?';\n    p.com_agua = atoi(ag) != 0;\n    p.pm = (int16_t)atoi(pm);\n    p.canhao = atoi(cn) != 0;\n    if (pt[0] == 'g') { p.parada = POR_GRAUS; p.graus = (uint32_t)strtoul(pv, nullptr, 10); }\n    else if (pt[0] == 't') { p.parada = POR_DURACAO; p.duracao_s = (uint32_t)strtoul(pv, nullptr, 10); }\n    else return _erro(msg, sz, \"pivo_parada_invalida\");\n    const char* f = strtok_r(nullptr, \" \", &sv);\n    if (f && f[0] == 'f') {\n        const char* fd = strtok_r(nullptr, \" \", &sv);\n        const char* fl = strtok_r(nullptr, \" \", &sv);\n        if (!fd || !fl) return _erro(msg, sz, \"pivo_faixa_invalida\");\n        p.tem_faixa = true; p.desliga_em = (uint16_t)atoi(fd); p.liga_em = (uint16_t)atoi(fl);\n    }\n    // I/O minimo para o plano\n    if ((p.dir == 'D' && !_bo[BO_DIR]) || (p.dir == 'E' && !_bo[BO_ESQ]) || !_bo[BO_PERC] || (p.com_agua && !_bo[BO_BOMBA]))\n        return _erro(msg, sz, \"pivo_io_incompleto\");\n    if ((p.parada == POR_GRAUS || p.tem_faixa) && !_enc_res) return _erro(msg, sz, \"pivo_sem_encoder\");\n    char mot[40];\n    if (!_m->ligar(p, millis(), mot, sizeof(mot))) { snprintf(msg, sz, \"pivo_%s\", mot); return 0; }\n    return _ok(msg, sz, \"pivo_ligando\");\n}\n\n// \"perc ...\" do firmware anterior (sequencia no servidor). -1 = nao e' perc.\nstatic int _cmdPercLegado(const String& cmd, char* msg, size_t sz) {\n    if (!cmd.startsWith(\"perc\")) return -1;\n    if (_m && _m->estado() != PARADO) return _erro(msg, sz, \"perc_pivo_local_ligado\");\n    if (cmd.indexOf(\"off\") >= 0) {\n        if (_leg_bo) relay_set(_leg_bo, false);\n        _leg_pm = -1; _leg_ini = 0; _leg_saida = -1; _perc_on = false;\n        for (int k = 0; k < 6; k++) if (_bo[k] == _leg_bo) _apl[k] = -1;\n        return _ok(msg, sz, \"perc_off\");\n    }\n    int bo = 0, pm = -1, cy = 60, mk = 0;\n    if (sscanf(cmd.c_str(), \"perc %d %d %d %d\", &bo, &pm, &cy, &mk) < 2 || bo < 1 || bo > PIVO_IO_MAX || pm < 0 || pm > 1000 || cy < 5 || cy > 600 || mk < 0 || mk > 255)\n        return _erro(msg, sz, \"perc_invalido\");\n    if (_leg_bo && _leg_bo != bo) relay_set(_leg_bo, false);\n    bool emCiclo = _leg_pm >= 0 && _leg_bo == bo && _leg_ini;\n    _leg_bo = (uint8_t)bo; _leg_ciclo_ms = (uint32_t)cy * 1000UL; _leg_mask = (uint8_t)mk; _leg_pm = (int16_t)pm;\n    if (!emCiclo) { _leg_ini = 0; _leg_saida = -1; }\n    Serial.printf(\"[PIVO] perc legado: BO%d %d.%d%% ciclo %ds mascara 0x%02X\\n\", bo, pm / 10, pm % 10, cy, mk);\n    snprintf(msg, sz, \"perc_%d_%d\", bo, pm);\n    return 1;\n}\n\nint pivo_cmd(const String& cmd, char* msg, size_t sz) {\n    { int r = _cmdPercLegado(cmd, msg, sz); if (r >= 0) return r; }\n    if (!cmd.startsWith(\"pivo \") && cmd != \"pivo\") return -1;\n    if (!_m) return _erro(msg, sz, \"pivo_nao_iniciado\");\n    char buf[200];\n    String a = cmd.substring(4); a.trim();\n    strncpy(buf, a.c_str(), sizeof(buf) - 1); buf[sizeof(buf) - 1] = 0;\n    char* sv = nullptr;\n    char* verbo = strtok_r(buf, \" \", &sv);\n    char* resto = sv;\n    if (!verbo) return _erro(msg, sz, \"pivo_cmd_vazio\");\n\n    if (!strcmp(verbo, \"ligar\")) return _cmdLigar(resto ? resto : (char*)\"\", msg, sz);\n\n    if (!strcmp(verbo, \"desligar\")) {\n        // Parar = desligar: SEMPRE desliga (spec 2.3/6.6), tudo LOW de uma vez.\n        Estado e = _m->estado();\n        _m->desligar(M_COMANDO, millis());\n        // Alem da sequencia: BOs do pivo ligadas por fora (rN on, percentimetro legado) tambem caem.\n        for (int k = 0; k < 6; k++) if (_bo[k]) { relay_set(_bo[k], false); _apl[k] = 0; }\n        if (_leg_bo) relay_set(_leg_bo, false);\n        _leg_pm = -1; _leg_ini = 0; _leg_saida = -1; _perc_on = false;\n        pivo_publicar_agora();\n        return _ok(msg, sz, e == PARADO ? \"pivo_ja_parado\" : \"pivo_parada_executada\");\n    }\n    if (!strcmp(verbo, \"perc\")) {\n        char mot[32];\n        int pm = resto ? atoi(resto) : -1;\n        if (!_m->ajustarPercentimetro((int16_t)pm, mot, sizeof(mot))) { snprintf(msg, sz, \"pivo_%s\", mot); return 0; }\n        snprintf(msg, sz, \"pivo_perc_%d\", pm);\n        return 1;\n    }\n    if (!strcmp(verbo, \"canhao\")) {\n        // \"pivo canhao <0|1> [f <desliga_em> <liga_em>]\" — ajuste em operacao (spec 2.2/6.5)\n        char mot[32];\n        int on = 0, fd = -1, fl = -1;\n        char fch = 0;\n        int n = resto ? sscanf(resto, \"%d %c %d %d\", &on, &fch, &fd, &fl) : 0;\n        bool faixa = n == 4 && fch == 'f';\n        if (n < 1) return _erro(msg, sz, \"pivo_canhao_invalido\");\n        if (!_m->ajustarCanhao(on != 0, faixa, faixa ? (uint16_t)fd : 0, faixa ? (uint16_t)fl : 0, millis(), mot, sizeof(mot))) {\n            snprintf(msg, sz, \"pivo_canhao_%s\", mot); return 0;\n        }\n        _apl[BO_CANHAO] = -1;   // reescreve a BO06\n        return _ok(msg, sz, on ? \"pivo_canhao_on\" : \"pivo_canhao_off\");\n    }\n    if (!strcmp(verbo, \"status\")) {\n        // Estado no proprio ack (chega mesmo no satelite LoRa, onde o status so' sai no POLL):\n        // \"pivo_st <etapa> <passo> <permil> <motivo> a<alertas> ...\" — etapa 0 parado, 1 aguardando pressao/giro, 2 girando.\n        pivo_publicar_agora();\n        const char* f = motivoNome(_m->motivo());\n        // + diagnostico: r<estado dos reles no driver, hex: bit n = Rn> i<recuperacoes do I2C dos reles> x<1 = reles sem controle> o<saidas pedidas: bit0 bomba..5 canhao>\n        const Saidas& so = _m->saidas();\n        uint8_t ob = (so.bomba ? 1 : 0) | (so.valvula ? 2 : 0) | (so.dir ? 4 : 0) | (so.esq ? 8 : 0) | (_perc_on ? 16 : 0) | (so.canhao ? 32 : 0);\n        snprintf(msg, sz, \"pivo_st %d %d %d %s a%u k%04X r%02X i%lu x%d o%02X\", (int)_m->estado(), (int)_m->passo(), (int)so.perc_pm, f,\n                 (unsigned)_m->alertas(), (unsigned)_cfg_ck, (unsigned)relays_get_state(), (unsigned long)diag_i2c_resets, relays_io_fault() ? 1 : 0, (unsigned)ob);\n        return 1;\n    }\n    if (!strcmp(verbo, \"encler\")) {\n        // Calibracao do angulo (NEXON-103): 5 leituras Modbus SEGUIDAS do encoder, so' com o pivo parado\n        // (a leitura bloqueia o loop). Tudo no proprio ack, que chega ate' pelo LoRa:\n        //   \"pivo_el <v1> <v2> <v3> <v4> <v5>\"  as 5 leituras boas (contagem crua)\n        //   \"pivo_el_erro <n>\"                  falhou depois de n leituras boas (erro ou timeout)\n        // Quem decide se vale (iguais ou +-1) e' o NexON. Devolve 1 nos dois casos: a TON respondeu.\n        if (_m->estado() != PARADO) return _erro(msg, sz, \"pivo_ligado\");\n        if (!pivo_encoder_amostrar) return _erro(msg, sz, \"pivo_sem_encoder\");\n        size_t n = (size_t)snprintf(msg, sz, \"pivo_el\");\n        for (int k = 0; k < 5; k++) {\n            if (k) delay(60);\n            _enc_novo = false;\n            if (!pivo_encoder_amostrar() || !_enc_novo) { snprintf(msg, sz, \"pivo_el_erro %d\", k); return 1; }\n            if (n < sz) n += (size_t)snprintf(msg + n, sz - n, \" %lu\", (unsigned long)lroundf(_enc_bruto));\n        }\n        return 1;\n    }\n    if (!strcmp(verbo, \"mostrar\")) {   // imprime a configuracao na Serial\n        Serial.printf(\"[PIVO] cfg=%d BO %u %u %u %u %u %u | BI %u %u %u %u %u %u inv=0x%02X | tempos %lu %lu %lu %lu %lu %lu %lu %lu %lu | enc %lu inv=%d zero=%.1f\\n\",\n            _cfg_ok, _bo[0], _bo[1], _bo[2], _bo[3], _bo[4], _bo[5], _bi[0], _bi[1], _bi[2], _bi[3], _bi[4], _bi[5], _inv,\n            (unsigned long)_tp[0], (unsigned long)_tp[1], (unsigned long)_tp[2], (unsigned long)_tp[3], (unsigned long)_tp[4],\n            (unsigned long)_tp[5], (unsigned long)_tp[6], (unsigned long)_tp[7], (unsigned long)_tp[8],\n            (unsigned long)_enc_res, _enc_inv, _enc_zero);\n        return _ok(msg, sz, \"pivo_cfg_printed\");\n    }\n\n    // Configuracao: so' com o pivo parado (trocar I/O com saida ligada deixaria rele preso).\n    bool cfgCmd = !strcmp(verbo, \"cfg\") || !strcmp(verbo, \"io\") || !strcmp(verbo, \"tempos\") || !strcmp(verbo, \"enc\");\n    if (cfgCmd && _m->estado() != PARADO) return _erro(msg, sz, \"pivo_ligado\");\n\n    if (!strcmp(verbo, \"cfg\")) {\n        // Configuracao inteira num comando (cabe no LoRa): \"pivo cfg <BOs> <BIs> <inv> <9 tempos> <resolucao>\"\n        //   BOs/BIs = 6 digitos (0 = nao ligado; papeis na ordem do \"pivo io\"), inv = 6 digitos 0/1\n        //   tempos = os 9 do \"pivo tempos\"; resolucao do encoder (0 = sem encoder; angulo BRUTO).\n        // Guarda o CRC16 do texto: o \"pivo status\" devolve \"k<crc>\" e o NexON so' reenvia se mudou.\n        char bs[8] = \"\", is[8] = \"\", inv[8] = \"\";\n        unsigned long t[PIVO_NTP], res = 0;\n        if (!resto || sscanf(resto, \"%7s %7s %7s %lu %lu %lu %lu %lu %lu %lu %lu %lu %lu\", bs, is, inv,\n                &t[0], &t[1], &t[2], &t[3], &t[4], &t[5], &t[6], &t[7], &t[8], &res) != 13\n            || strlen(bs) != 6 || strlen(is) != 6 || strlen(inv) != 6)\n            return _erro(msg, sz, \"pivo_cfg_invalido\");\n        static const unsigned long lo[PIVO_NTP] = {5,    5,   1,   0,  0,  0,  10,   30,   5};\n        static const unsigned long hi[PIVO_NTP] = {1800, 600, 120, 60, 60, 60, 3600, 3600, 600};\n        uint8_t nb[6], ni[6], m = 0;\n        for (int k = 0; k < 6; k++) {\n            if (bs[k] < '0' || bs[k] > '0' + PIVO_IO_MAX || is[k] < '0' || is[k] > '0' + PIVO_IO_MAX || (inv[k] != '0' && inv[k] != '1'))\n                return _erro(msg, sz, \"pivo_cfg_faixa\");\n            nb[k] = (uint8_t)(bs[k] - '0'); ni[k] = (uint8_t)(is[k] - '0');\n            for (int j = 0; j < k; j++) if (nb[k] && nb[k] == nb[j]) return _erro(msg, sz, \"pivo_bo_repetida\");\n            if (inv[k] == '1') m |= (1 << k);\n        }\n        for (int k = 0; k < PIVO_NTP; k++) if (t[k] < lo[k] || t[k] > hi[k]) return _erro(msg, sz, \"pivo_cfg_faixa\");\n        if (res != 0 && (res < 2 || res > 1000000UL)) return _erro(msg, sz, \"pivo_cfg_faixa\");\n        for (int k = 0; k < 6; k++) if (_bo[k] && _bo[k] != nb[k]) relay_set(_bo[k], false);   // mapa mudou: BO antiga em OFF\n        for (int k = 0; k < 6; k++) { _bo[k] = nb[k]; _bi[k] = ni[k]; _apl[k] = -1; }\n        _inv = m;\n        for (int k = 0; k < PIVO_NTP; k++) _tp[k] = (uint32_t)t[k];\n        _enc_res = (uint32_t)res; _enc_inv = false; _enc_zero = 0;\n        _cfg_ok = true;\n        String args = String(resto); args.trim();\n        _cfg_ck = _crc16(args.c_str());\n        _salvarCfg();\n        _m->configurar(_montarConfig());\n        pivo_publicar_agora();\n        snprintf(msg, sz, \"pivo_cfg_ok k%04X\", (unsigned)_cfg_ck);\n        return 1;\n    }\n    if (!strcmp(verbo, \"io\")) {\n        int b[6], i[6]; char inv[8] = \"\";\n        if (!resto || sscanf(resto, \"%d %d %d %d %d %d %d %d %d %d %d %d %7s\",\n                &b[0], &b[1], &b[2], &b[3], &b[4], &b[5], &i[0], &i[1], &i[2], &i[3], &i[4], &i[5], inv) != 13 || strlen(inv) != 6)\n            return _erro(msg, sz, \"pivo_io_invalido\");\n        for (int k = 0; k < 6; k++) {\n            if (b[k] < 0 || b[k] > PIVO_IO_MAX || i[k] < 0 || i[k] > PIVO_IO_MAX) return _erro(msg, sz, \"pivo_io_faixa\");\n            for (int j = 0; j < k; j++) if (b[k] && b[k] == b[j]) return _erro(msg, sz, \"pivo_bo_repetida\");\n            if (inv[k] != '0' && inv[k] != '1') return _erro(msg, sz, \"pivo_inv_invalido\");\n        }\n        // Desliga as BOs antigas antes de trocar o mapa\n        for (int k = 0; k < 6; k++) if (_bo[k]) relay_set(_bo[k], false);\n        uint8_t m = 0;\n        for (int k = 0; k < 6; k++) { _bo[k] = (uint8_t)b[k]; _bi[k] = (uint8_t)i[k]; if (inv[k] == '1') m |= (1 << k); _apl[k] = -1; }\n        _inv = m;\n        _cfg_ok = true;\n        _cfg_ck = 0;   // mexeu por fora do \"pivo cfg\": o NexON reenvia a config inteira na proxima partida\n        _salvarCfg();\n        _m->configurar(_montarConfig());\n        pivo_publicar_agora();\n        return _ok(msg, sz, \"pivo_io_ok\");\n    }\n    if (!strcmp(verbo, \"tempos\")) {\n        unsigned long t[PIVO_NTP];\n        if (!resto || sscanf(resto, \"%lu %lu %lu %lu %lu %lu %lu %lu %lu\", &t[0], &t[1], &t[2], &t[3], &t[4], &t[5], &t[6], &t[7], &t[8]) != PIVO_NTP)\n            return _erro(msg, sz, \"pivo_tempos_invalido\");\n        //                                       espera giro canhao tolP tolT tolL sempos janela ciclo\n        static const unsigned long lo[PIVO_NTP] = {5,    5,   1,     0,   0,   0,   10,    30,    5};\n        static const unsigned long hi[PIVO_NTP] = {1800, 600, 120,   60,  60,  60,  3600,  3600,  600};\n        for (int k = 0; k < PIVO_NTP; k++) if (t[k] < lo[k] || t[k] > hi[k]) return _erro(msg, sz, \"pivo_tempos_faixa\");\n        for (int k = 0; k < PIVO_NTP; k++) _tp[k] = (uint32_t)t[k];\n        _cfg_ck = 0;\n        _salvarCfg();\n        _m->configurar(_montarConfig());\n        return _ok(msg, sz, \"pivo_tempos_ok\");\n    }\n    if (!strcmp(verbo, \"enc\")) {\n        unsigned long res = 0; int inv = 0; float zero = 0;\n        if (!resto || sscanf(resto, \"%lu %d %f\", &res, &inv, &zero) != 3 || (res != 0 && (res < 2 || res > 1000000UL)) || !(zero >= -360.0f && zero <= 360.0f))\n            return _erro(msg, sz, \"pivo_enc_invalido\");\n        _enc_res = (uint32_t)res; _enc_inv = inv != 0; _enc_zero = zero;\n        _cfg_ck = 0;\n        _salvarCfg();\n        return _ok(msg, sz, \"pivo_enc_ok\");\n    }\n    return _erro(msg, sz, \"pivo_cmd_desconhecido\");\n}\n",
  };
  return {
    files: function () { var o = {}; for (var k in FILES) o[k] = FILES[k]; return o; },
  };
})();
